27	// setupFeedingRequestLedger 在 dir 建立一份正常台账并关闭：
28	//   - B1（执行中）：feed-1 登记 M1 1.000 克（序号 1，结果显示为 1），
29	//     feed-2 登记 M1 3 克（序号 2，另一登记人）；
30	//   - B2（执行中）：feed-b2 登记 M1 5 克（序号 1，与 B1 各自编号）。
31	//
32	// 返回落盘后的台账文件内容，供各用例改坏后重写。
33	func setupFeedingRequestLedger(t *testing.T, dir string) []byte {
34		t.Helper()
35		s, err := Open(dir)
36		if err != nil {
37			t.Fatalf("Open 失败: %v", err)
38		}
39		registerStandardRecipe(t, s, "recipe-1") // M1=100、M2=0.5、M3=0.010
40		if _, err := s.CreateBatch("b1", "B1", "R1", "v1", 10); err != nil {
41			t.Fatal(err)
42		}
43		if _, err := s.StartBatch("s1", "B1"); err != nil {
44			t.Fatal(err)
45		}
46		if _, err := s.CreateBatch("b2", "B2", "R1", "v1", 5); err != nil {
47			t.Fatal(err)
48		}
49		if _, err := s.StartBatch("s2", "B2"); err != nil {
50			t.Fatal(err)
51		}
52		t1 := feedingRequestBaseTime()
53		if _, err := s.AddFeeding("feed-1", "B1", "M1", "1.000", t1, "张三"); err != nil {
54			t.Fatal(err)
55		}
56		if _, err := s.AddFeeding("feed-2", "B1", "M1", "3", t1.Add(2*time.Hour), "王五"); err != nil {
57			t.Fatal(err)
58		}
59		if _, err := s.AddFeeding("feed-b2", "B2", "M1", "5", t1.Add(time.Hour), "李四"); err != nil {
60			t.Fatal(err)
61		}
62		if err := s.Close(); err != nil {
63			t.Fatal(err)
64		}
65		good, err := os.ReadFile(filepath.Join(dir, stateFileName))
66		if err != nil {
67			t.Fatal(err)
68		}
