70	}
71	
72	// corruptFeedingRequestResult 把正常台账内容中 feed-1 请求的保存结果替换为
73	// mutate 给出的值（mutate 返回 nil 表示删除该字段），返回改写后的文件内容。
74	func corruptFeedingRequestResult(t *testing.T, good []byte, mutate func() json.RawMessage) []byte {
75		t.Helper()
76		var st persistedState
77		if err := json.Unmarshal(good, &st); err != nil {
78			t.Fatal(err)
79		}
80		req := st.Requests["feed-1"]
81		if req == nil {
82			t.Fatalf("正常台账中应存在 feed-1 请求记录")
83		}
84		req.Result = mutate()
85		data, err := json.MarshalIndent(&st, "", "  ")
86		if err != nil {
87			t.Fatal(err)
88		}
89		return data
90	}
91	
92	// marshalFeedingView 把一条投料视图序列化为保存结果使用的 JSON。
93	func marshalFeedingView(t *testing.T, v FeedingView) json.RawMessage {
94		t.Helper()
95		raw, err := json.Marshal(v)
96		if err != nil {
97			t.Fatal(err)
98		}
99		return raw
100	}
