		t.Fatalf("B2 应有 1 条序号为 1 的投料: %+v", view2.Feedings)
	}

	// 新请求编号提交相同内容仍是新的一次投料，取得连续序号。
	f, err := s.AddFeeding("feed-3", "B1", "M1", "2", t1, "张三")
